/**
 * Tests for `insertProposal` — shared bot_modal_proposals row inserter used by
 * both Wave 3 slash dispatcher (Builder 3) and Wave 7 bot LLM intercept
 * (Builder 7). DB-level cases require RUNWAY_DATABASE_URL.
 *
 * The helper test suite is split into:
 *   - pure-helper unit tests (default export shape, ID prefix, expiresAt math)
 *     — always run.
 *   - DB-level integration tests — skipped via `describe.skipIf` when
 *     RUNWAY_DATABASE_URL is not set, mirroring the pattern in
 *     `runway-schema.test.ts`.
 */
import { describe, it, expect, vi } from "vitest";
import { eq } from "drizzle-orm";
import { botModalProposals } from "@/lib/db/runway-schema";
import { insertProposal } from "./proposal";

describe("insertProposal — pure helper invariants", () => {
  // The helper computes a fresh proposal id and expiresAt timestamp before
  // hitting the DB. We mock `getRunwayDb` to capture the row payload without
  // a live database. This protects the prefix + TTL contract that callers
  // (Builder 3 + Builder 7) rely on.
  it("computes id with prefix 'prop_' and expiresAt = now + 30 min by default", async () => {
    const inserts: unknown[] = [];
    vi.resetModules();
    vi.doMock("@/lib/db/runway", () => ({
      getRunwayDb: () => ({
        insert: () => ({
          values: (row: unknown) => {
            inserts.push(row);
            return Promise.resolve();
          },
        }),
      }),
    }));
    // Re-import after mocking so the mock binds.
    const mod = await import("./proposal");
    const before = Date.now();
    const out = await mod.insertProposal({
      kind: "create",
      toolName: "create_week_item",
      args: { title: "Foo" },
      userSlackId: "U_TEST_001",
      channelId: "C_TEST_001",
    });
    const after = Date.now();

    expect(out.proposalId).toMatch(/^prop_/);

    // Inspect the captured row.
    expect(inserts).toHaveLength(1);
    const row = inserts[0] as Record<string, unknown>;
    expect(row.id).toBe(out.proposalId);
    expect(row.kind).toBe("create");
    expect(row.toolName).toBe("create_week_item");
    expect(row.userSlackId).toBe("U_TEST_001");
    expect(row.channelId).toBe("C_TEST_001");
    expect(row.status).toBe("pending");
    expect(row.args).toBe(JSON.stringify({ title: "Foo" }));
    expect(row.targetEntityId).toBeNull();
    expect(row.targetEntityType).toBeNull();

    // expiresAt should be ~30 min after createdAt
    const createdAt = (row.createdAt as Date).getTime();
    const expiresAt = (row.expiresAt as Date).getTime();
    expect(createdAt).toBeGreaterThanOrEqual(before);
    expect(createdAt).toBeLessThanOrEqual(after);
    // Default TTL = 30 min = 1_800_000 ms
    expect(expiresAt - createdAt).toBe(30 * 60 * 1000);

    vi.doUnmock("@/lib/db/runway");
  });

  it("respects ttlMinutes override (e.g. 5 min for tests)", async () => {
    const inserts: unknown[] = [];
    vi.resetModules();
    vi.doMock("@/lib/db/runway", () => ({
      getRunwayDb: () => ({
        insert: () => ({
          values: (row: unknown) => {
            inserts.push(row);
            return Promise.resolve();
          },
        }),
      }),
    }));
    const mod = await import("./proposal");
    await mod.insertProposal({
      kind: "create",
      toolName: "create_team_member",
      args: {},
      userSlackId: "U2",
      channelId: "C2",
      ttlMinutes: 5,
    });
    const row = inserts[0] as Record<string, unknown>;
    const createdAt = (row.createdAt as Date).getTime();
    const expiresAt = (row.expiresAt as Date).getTime();
    expect(expiresAt - createdAt).toBe(5 * 60 * 1000);
    vi.doUnmock("@/lib/db/runway");
  });

  it("propagates kind='edit' fields (targetEntityId + targetEntityType)", async () => {
    const inserts: unknown[] = [];
    vi.resetModules();
    vi.doMock("@/lib/db/runway", () => ({
      getRunwayDb: () => ({
        insert: () => ({
          values: (row: unknown) => {
            inserts.push(row);
            return Promise.resolve();
          },
        }),
      }),
    }));
    const mod = await import("./proposal");
    await mod.insertProposal({
      kind: "edit",
      toolName: "update_project",
      args: { name: "AG1 Pro" },
      userSlackId: "U3",
      channelId: "C3",
      targetEntityId: "proj_123",
      targetEntityType: "project",
    });
    const row = inserts[0] as Record<string, unknown>;
    expect(row.kind).toBe("edit");
    expect(row.targetEntityId).toBe("proj_123");
    expect(row.targetEntityType).toBe("project");
    expect(row.toolName).toBe("update_project");
    vi.doUnmock("@/lib/db/runway");
  });

  it("propagates intentGroupId, parentProposalId, pendingProjectName, threadTs", async () => {
    const inserts: unknown[] = [];
    vi.resetModules();
    vi.doMock("@/lib/db/runway", () => ({
      getRunwayDb: () => ({
        insert: () => ({
          values: (row: unknown) => {
            inserts.push(row);
            return Promise.resolve();
          },
        }),
      }),
    }));
    const mod = await import("./proposal");
    await mod.insertProposal({
      kind: "create",
      toolName: "create_week_item",
      args: { title: "Brief draft" },
      userSlackId: "U4",
      channelId: "C4",
      threadTs: "1700000000.000099",
      intentGroupId: "ig_xyz",
      parentProposalId: "prop_parent",
      pendingProjectName: "AG1 Pro 2026",
    });
    const row = inserts[0] as Record<string, unknown>;
    expect(row.threadTs).toBe("1700000000.000099");
    expect(row.intentGroupId).toBe("ig_xyz");
    expect(row.parentProposalId).toBe("prop_parent");
    expect(row.pendingProjectName).toBe("AG1 Pro 2026");
    vi.doUnmock("@/lib/db/runway");
  });

  it("serializes args as JSON string", async () => {
    const inserts: unknown[] = [];
    vi.resetModules();
    vi.doMock("@/lib/db/runway", () => ({
      getRunwayDb: () => ({
        insert: () => ({
          values: (row: unknown) => {
            inserts.push(row);
            return Promise.resolve();
          },
        }),
      }),
    }));
    const mod = await import("./proposal");
    const args = { a: 1, b: "two", c: [3, 4], d: { nested: true } };
    await mod.insertProposal({
      kind: "create",
      toolName: "create_project",
      args,
      userSlackId: "U5",
      channelId: "C5",
    });
    const row = inserts[0] as Record<string, unknown>;
    expect(typeof row.args).toBe("string");
    expect(JSON.parse(row.args as string)).toEqual(args);
    vi.doUnmock("@/lib/db/runway");
  });
});

// ============================================================
// DB-level integration test — round-trips a proposal through the real
// schema. Skipped when RUNWAY_DATABASE_URL is not set.
// ============================================================
describe.skipIf(!process.env.RUNWAY_DATABASE_URL)(
  "insertProposal (DB-level)",
  () => {
    it("inserts a row that round-trips through botModalProposals", async () => {
      const { getRunwayDb } = await import("@/lib/db/runway");
      const db = getRunwayDb();
      const out = await insertProposal({
        kind: "create",
        toolName: "create_week_item",
        args: { title: "DB test task" },
        userSlackId: "U_DB_TEST",
        channelId: "C_DB_TEST",
      });
      try {
        const rows = await db
          .select()
          .from(botModalProposals)
          .where(eq(botModalProposals.id, out.proposalId))
          .limit(1);
        expect(rows).toHaveLength(1);
        expect(rows[0].kind).toBe("create");
        expect(rows[0].status).toBe("pending");
        expect(rows[0].toolName).toBe("create_week_item");
      } finally {
        await db
          .delete(botModalProposals)
          .where(eq(botModalProposals.id, out.proposalId));
      }
    });
  },
);

/**
 * Shared insertProposal helper — Builders 3 and 7.
 *
 * Used by:
 *   - `/api/slack/commands` route (Wave 3 / Builder 3) — slash dispatcher
 *     stages a fresh `pending` row before opening the modal so the
 *     view_submission handler can locate the proposal by `private_metadata`.
 *   - bot LLM intercept `interceptCreateForModal` (Wave 7 / Builder 7) — same
 *     contract: stage row + return id, do NOT call `views.open` here. The
 *     bot wrapper appends button blocks that carry the proposalId in
 *     `value` and the open_create_modal action handler consumes the
 *     fresh slash-webhook trigger_id to call views.open.
 *
 * Lifecycle is owned by the Wave 12 expiry sweeper and the
 * view_submission/view_closed handlers — this helper only inserts `pending`
 * rows. It does NOT mutate or delete proposals.
 */

import { getRunwayDb } from "@/lib/db/runway";
import { botModalProposals } from "@/lib/db/runway-schema";
import { generateId } from "@/lib/runway/operations-utils";

export type ProposalKind = "create" | "edit";
export type ProposalTargetEntityType = "project" | "week_item" | "team_member";

/**
 * Inputs for staging a fresh `bot_modal_proposals` row.
 *
 * - `kind`           - "create" or "edit"; discriminates the row.
 * - `toolName`       - one of: create_project | create_week_item |
 *                       create_team_member | update_project | update_week_item |
 *                       update_team_member.
 * - `args`           - JSON-serializable LLM-extracted args (or current values
 *                       for edit). Stored as a JSON string in the column.
 * - `userSlackId`    - Slack user id who triggered (slash or DM).
 * - `channelId`      - Slack channel where the trigger arrived (DM or channel).
 * - `threadTs`       - Optional parent thread_ts (for threaded DMs).
 * - `targetEntityId` / `targetEntityType` - Set for edit kinds.
 * - `parentProposalId` - Multi-detect chaining: child task -> parent project.
 * - `intentGroupId`  - Groups proposals from one user message.
 * - `pendingProjectName` - Hint for parent-project lookup before parent saved.
 * - `ttlMinutes`     - Default 30. Tunable for tests.
 */
export interface InsertProposalParams {
  kind: ProposalKind;
  toolName: string;
  args: Record<string, unknown>;
  userSlackId: string;
  channelId: string;
  threadTs?: string | null;
  targetEntityId?: string;
  targetEntityType?: ProposalTargetEntityType;
  parentProposalId?: string;
  intentGroupId?: string;
  pendingProjectName?: string;
  conversationRef?: string;
  ttlMinutes?: number;
}

const DEFAULT_TTL_MINUTES = 30;
const PROPOSAL_ID_PREFIX = "prop_";

/**
 * Insert a fresh `pending` proposal row. Returns the generated id so the
 * caller can wire it into the modal `private_metadata` (slash flow) or the
 * Block Kit button `value` (bot intercept flow).
 */
export async function insertProposal(
  params: InsertProposalParams,
): Promise<{ proposalId: string }> {
  const db = getRunwayDb();
  const id = `${PROPOSAL_ID_PREFIX}${generateId()}`;
  const createdAt = new Date();
  const ttlMs =
    (params.ttlMinutes ?? DEFAULT_TTL_MINUTES) * 60 * 1000;
  const expiresAt = new Date(createdAt.getTime() + ttlMs);

  await db.insert(botModalProposals).values({
    id,
    userSlackId: params.userSlackId,
    channelId: params.channelId,
    threadTs: params.threadTs ?? null,
    toolName: params.toolName,
    kind: params.kind,
    targetEntityId: params.targetEntityId ?? null,
    targetEntityType: params.targetEntityType ?? null,
    args: JSON.stringify(params.args),
    conversationRef: params.conversationRef ?? null,
    parentProposalId: params.parentProposalId ?? null,
    intentGroupId: params.intentGroupId ?? null,
    pendingProjectName: params.pendingProjectName ?? null,
    postedMessageTs: null,
    postedMessageChannel: null,
    createdAt,
    expiresAt,
    status: "pending",
    statusReason: null,
    resolvedProjectId: null,
  });

  return { proposalId: id };
}

/**
 * Shared test helpers for Slack slash-commands route tests.
 *
 * Mirrors the pattern in `events/route-test-helpers.ts` (HMAC-signed Request
 * factory) but produces an `application/x-www-form-urlencoded` body suited for
 * Slack slash commands. The body payload is built from a fixture-style
 * key/value object (matches the parsed shape stored in
 * `tests/fixtures/slack/slash-command-*.json`).
 */

import { makeSlackSignature, nowTimestamp } from "@/lib/slack/test-helpers";

export function encodeFormBody(payload: Record<string, string>): string {
  const params = new URLSearchParams();
  for (const [k, v] of Object.entries(payload)) {
    // Drop fixture-only meta keys that start with `_`.
    if (k.startsWith("_")) continue;
    params.set(k, v);
  }
  return params.toString();
}

export function makeSlashRequest(
  payload: Record<string, string>,
  options?: {
    signature?: string | null;
    timestamp?: string | null;
    signingSecret?: string;
    bodyOverride?: string;
  },
): Request {
  const secret = options?.signingSecret ?? "test_secret";
  const ts = options?.timestamp ?? nowTimestamp();
  const body = options?.bodyOverride ?? encodeFormBody(payload);
  const sig =
    options?.signature !== undefined
      ? options.signature
      : makeSlackSignature(secret, ts, body);

  const headers: Record<string, string> = {
    "Content-Type": "application/x-www-form-urlencoded",
  };
  if (sig !== null) headers["x-slack-signature"] = sig;
  if (ts !== null) headers["x-slack-request-timestamp"] = ts;

  return new Request("http://localhost/api/slack/commands", {
    method: "POST",
    headers,
    body,
  });
}

/**
 * Tests for `/api/slack/commands` POST route — Wave 3 / Builder 3.
 *
 * Coverage:
 *   - HMAC verification: missing secret, invalid signature, missing/null
 *     signature, stale timestamp.
 *   - Each of the 6 commands routes to the correct flow (3 create + 3 edit).
 *   - Create flow: empty text -> empty proposal + view_open with no
 *     `multiMatchHint`; text with parent name -> fuzzyMatchCandidates against
 *     mocked projects; multi-match (>1) populates `multiMatchHint`.
 *   - Edit flow lookup: ID match (ulid-shape), single fuzzy match, multi-match,
 *     no-match (ephemeral, no proposal).
 *   - Multi-match hint computation matrix: 0 / 1 / N candidates / absent name.
 *   - 3s budget assertion.
 *
 * Strategy: Mock `@/lib/slack/client`, `@/lib/db/runway`, and the runway data
 * helpers. The route under test consumes:
 *   - `getRunwayDb()` -> insertProposal (already DB-mocked by capturing inserts)
 *   - `getSlackClient().views.open(trigger_id, view)` -> spied
 *   - project / week_item / team_member fetchers -> stubbed with deterministic
 *     fixtures so fuzzy match is reproducible.
 */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { makeSlackSignature, nowTimestamp, loadFixture } from "@/lib/slack/test-helpers";
import { makeSlashRequest, encodeFormBody } from "./route-test-helpers";

// ────────────────────────────────────────────────────────────────────────────
// Fixture project / week_item / team_member rows. We keep them tiny and
// reproducible: `Brand Refresh` and `Brand Strategy` will both fuzzy-match
// "Brand"; `AG1 Pro Subscriber 2026` only matches "AG1 Pro" at >= 0.6.
// ────────────────────────────────────────────────────────────────────────────
const FIXTURE_PROJECTS = [
  { id: "proj_brand_refresh", name: "Brand Refresh", clientId: "cli_ag1" },
  { id: "proj_brand_strategy", name: "Brand Strategy", clientId: "cli_ag1" },
  { id: "proj_ag1_pro_2026", name: "AG1 Pro Subscriber 2026", clientId: "cli_ag1" },
  { id: "proj_landing_page", name: "Landing Page Copy", clientId: "cli_ag1" },
];

const FIXTURE_WEEK_ITEMS = [
  { id: "wi_concept_writeup", title: "Concept Writeup", clientId: "cli_ag1", projectId: "proj_brand_refresh" },
  { id: "wi_concept_review", title: "Concept Review", clientId: "cli_ag1", projectId: "proj_brand_refresh" },
];

const FIXTURE_TEAM_MEMBERS = [
  { id: "tm_lane", name: "Lane", fullName: "Lane Lopez", roleCategory: "creative" },
  { id: "tm_leslie", name: "Leslie", fullName: "Leslie Park", roleCategory: "dev" },
];

// Hoisted helper: shared `views.open` + `chat.postEphemeral` spies. We build
// fresh ones in each test scope via `vi.fn()` and rebind through `vi.doMock`.
function setupMocks() {
  const insertedProposals: unknown[] = [];
  const viewsOpen = vi.fn().mockResolvedValue({ ok: true });
  const chatPostEphemeral = vi.fn().mockResolvedValue({ ok: true });

  vi.resetModules();
  vi.doMock("@/lib/db/runway", () => ({
    getRunwayDb: () => ({
      insert: () => ({
        values: (row: unknown) => {
          insertedProposals.push(row);
          return Promise.resolve();
        },
      }),
      // For the edit-flow target lookup (look up by id or by name within client).
      select: () => ({
        from: (_table: unknown) => ({
          where: (_pred: unknown) => Promise.resolve([] as unknown[]),
          limit: (_n: number) => Promise.resolve([] as unknown[]),
        }),
      }),
    }),
  }));
  vi.doMock("@/lib/slack/client", () => ({
    getSlackClient: () => ({
      views: { open: viewsOpen },
      chat: { postEphemeral: chatPostEphemeral },
    }),
  }));
  // Stub runway data fetchers used by the route.
  vi.doMock("@/lib/runway/data-for-commands", () => ({
    getProjectsForFuzzy: vi.fn(async () => FIXTURE_PROJECTS),
    getWeekItemsForFuzzy: vi.fn(async () => FIXTURE_WEEK_ITEMS),
    getTeamMembersForFuzzy: vi.fn(async () => FIXTURE_TEAM_MEMBERS),
    getEntityById: vi.fn(async (kind: string, id: string) => {
      if (kind === "project") return FIXTURE_PROJECTS.find((p) => p.id === id) ?? null;
      if (kind === "week_item") return FIXTURE_WEEK_ITEMS.find((w) => w.id === id) ?? null;
      if (kind === "team_member") return FIXTURE_TEAM_MEMBERS.find((t) => t.id === id) ?? null;
      return null;
    }),
  }));
  return { insertedProposals, viewsOpen, chatPostEphemeral };
}

const SIGNING_SECRET = "test_secret";

describe("POST /api/slack/commands — HMAC + dispatch surface", () => {
  beforeEach(() => {
    process.env.SLACK_SIGNING_SECRET = SIGNING_SECRET;
  });

  it("returns 500 when SLACK_SIGNING_SECRET is missing", async () => {
    setupMocks();
    delete process.env.SLACK_SIGNING_SECRET;
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    const req = makeSlashRequest(fx);
    const res = await POST(req as never);
    expect(res.status).toBe(500);
  });

  it("returns 403 for invalid signature", async () => {
    setupMocks();
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    const req = makeSlashRequest(fx, { signature: "v0=invalid" });
    const res = await POST(req as never);
    expect(res.status).toBe(403);
  });

  it("returns 403 when signature header is null", async () => {
    setupMocks();
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    const req = makeSlashRequest(fx, { signature: null });
    const res = await POST(req as never);
    expect(res.status).toBe(403);
  });

  it("returns 403 for stale timestamp (older than 5 minutes)", async () => {
    setupMocks();
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    const stale = (Math.floor(Date.now() / 1000) - 600).toString();
    const body = encodeFormBody(fx);
    const sig = makeSlackSignature(SIGNING_SECRET, stale, body);
    const req = makeSlashRequest(fx, { timestamp: stale, signature: sig });
    const res = await POST(req as never);
    expect(res.status).toBe(403);
  });

  it("returns 200 within the 3-second budget for a valid create command", async () => {
    setupMocks();
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    const start = Date.now();
    const req = makeSlashRequest(fx);
    const res = await POST(req as never);
    const elapsed = Date.now() - start;
    expect(res.status).toBe(200);
    expect(elapsed).toBeLessThan(3000);
  });
});

describe("POST /api/slack/commands — create command flow", () => {
  beforeEach(() => {
    process.env.SLACK_SIGNING_SECRET = SIGNING_SECRET;
  });

  it("/runway-new-task with empty text inserts proposal + opens modal with no multiMatchHint", async () => {
    const { insertedProposals, viewsOpen } = setupMocks();
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    // fixture has command=/runway-new-task, text=""
    const req = makeSlashRequest(fx);
    const res = await POST(req as never);
    expect(res.status).toBe(200);
    expect(insertedProposals).toHaveLength(1);
    const row = insertedProposals[0] as Record<string, unknown>;
    expect(row.kind).toBe("create");
    expect(row.toolName).toBe("create_week_item");
    expect(row.userSlackId).toBe(fx.user_id);
    expect(row.channelId).toBe(fx.channel_id);
    // No parent name extracted -> no multiMatchHint passed to view builder.
    expect(viewsOpen).toHaveBeenCalledTimes(1);
    const callArgs = viewsOpen.mock.calls[0][0] as { trigger_id: string; view: { __debug?: { multiMatchHint?: string } } };
    expect(callArgs.trigger_id).toBe(fx.trigger_id);
    expect(callArgs.view.__debug?.multiMatchHint).toBeUndefined();
  });

  it("/runway-new-project with empty text routes to project create flow", async () => {
    const { insertedProposals, viewsOpen } = setupMocks();
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    const payload = { ...fx, command: "/runway-new-project", text: "" };
    const req = makeSlashRequest(payload);
    const res = await POST(req as never);
    expect(res.status).toBe(200);
    expect(insertedProposals).toHaveLength(1);
    const row = insertedProposals[0] as Record<string, unknown>;
    expect(row.toolName).toBe("create_project");
    expect(row.kind).toBe("create");
    expect(viewsOpen).toHaveBeenCalledTimes(1);
  });

  it("/runway-new-team-member routes to team_member create flow (no parent picker, no hint)", async () => {
    const { insertedProposals, viewsOpen } = setupMocks();
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    const payload = { ...fx, command: "/runway-new-team-member", text: "Lee" };
    const req = makeSlashRequest(payload);
    const res = await POST(req as never);
    expect(res.status).toBe(200);
    expect(insertedProposals).toHaveLength(1);
    const row = insertedProposals[0] as Record<string, unknown>;
    expect(row.toolName).toBe("create_team_member");
    expect(viewsOpen).toHaveBeenCalledTimes(1);
    const callArgs = viewsOpen.mock.calls[0][0] as { view: { __debug?: { multiMatchHint?: string } } };
    // Team member modal has no parent picker -> never compute multiMatchHint.
    expect(callArgs.view.__debug?.multiMatchHint).toBeUndefined();
  });

  it("/runway-new-task with text containing 'Brand' yields multiMatchHint (>=2 matches in fixture)", async () => {
    const { insertedProposals, viewsOpen } = setupMocks();
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    const payload = { ...fx, command: "/runway-new-task", text: "Concept Writeup Brand" };
    const req = makeSlashRequest(payload);
    const res = await POST(req as never);
    expect(res.status).toBe(200);
    expect(insertedProposals).toHaveLength(1);
    expect(viewsOpen).toHaveBeenCalledTimes(1);
    const callArgs = viewsOpen.mock.calls[0][0] as { view: { __debug?: { multiMatchHint?: string } } };
    expect(callArgs.view.__debug?.multiMatchHint).toBeDefined();
    expect(callArgs.view.__debug?.multiMatchHint).toContain("Brand");
  });

  it("/runway-new-task with single-match parent name yields no multiMatchHint", async () => {
    const { viewsOpen } = setupMocks();
    const { POST } = await import("./route");
    const fx = loadFixture<Record<string, string>>("slash-command-create");
    // "Landing Page Copy" only matches one fixture project.
    const payload = { ...fx, command: "/runway-new-task", text: "Concept review Landing Page Copy" };
    const req = makeSlashRequest(payload);
    const res = await POST(req as never);
